window.CIVIL_SET_DATA["past-13"] = {"title":"Past Paper Set 13","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-13-006","src":"PAST-13-006","text":"Where does the maximum ordinate on a mass haul diagram occur?","options":[{"key":"a","text":"The point where excavation ends and embankment starts"},{"key":"b","text":"The point where excavation starts"},{"key":"c","text":"The point where excavation ends"},{"key":"d","text":"All of the above"}],"answer":"a","explanation":"The mass curve rises through cutting and falls through filling. Its maximum therefore occurs at the change from cut to fill, where excavation ends and embankment begins.","marks":1,"source":{"kind":"past","set":13,"question":6,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q6 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-13-009","src":"PAST-13-009","text":"Given w/c = 0.8 and volume of cement = 2 m<sup>3</sup>, the water required in litres is","options":[{"key":"a","text":"2204 litres"},{"key":"b","text":"2304 litres"},{"key":"c","text":"2104 litres"},{"key":"d","text":"2310 litres"}],"answer":"b","explanation":"The cement mass is \\(2 \\times 1440 = 2880\\) kg, so \\[\\text{water} = 0.8 \\times 2880 = 2304\\] kg, which is 2304 litres.","marks":1,"source":{"kind":"past","set":13,"question":9,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q9 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-13-030","src":"PAST-13-030","text":"The moment of inertia through the centroid of a triangle parallel to its base is","options":[{"key":"a","text":"bd<sup>3</sup>/36"},{"key":"b","text":"bd<sup>4</sup>/36"},{"key":"c","text":"bd<sup>3</sup>/3"},{"key":"d","text":"bd<sup>3</sup>/6"}],"answer":"a","explanation":"For a triangle of base \\(b\\) and height \\(d\\), \\[I_G = \\dfrac{bd^3}{36}\\] About the base it is \\(\\dfrac{bd^3}{12}\\).","marks":1,"source":{"kind":"past","set":13,"question":30,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q30 · 1 mark"},"topic":"ACiE0104"},{"id":"PAST-13-035","src":"PAST-13-035","text":"The carpet area of a residential building is about …… (of the plinth area)","options":[{"key":"a","text":"50-65%"},{"key":"b","text":"75-80%"},{"key":"c","text":"78-80%"},{"key":"d","text":"90-95%"}],"answer":"a","explanation":"After walls, circulation (passages, stairs) and services are deducted, the carpet area of residential buildings is typically about 50–65% of the plinth area.","marks":1,"source":{"kind":"past","set":13,"question":35,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q35 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-13-037","src":"PAST-13-037","text":"The minimum width of a toilet door (residential) is","options":[{"key":"a","text":"750 mm"},{"key":"b","text":"450 mm"},{"key":"c","text":"350 mm"},{"key":"d","text":"100 mm"}],"answer":"a","explanation":"The key takes 750 mm as the minimum clear width of a residential toilet door, enough for a person to pass comfortably.","marks":1,"source":{"kind":"past","set":13,"question":37,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q37 · 1 mark"},"topic":"ACiE0103"},{"id":"PAST-13-042","src":"PAST-13-042","text":"The mortar to sand ratio provided in brick masonry for frog filling is","options":[{"key":"a","text":"1:1.5"},{"key":"b","text":"1:1"},{"key":"c","text":"1:4"},{"key":"d","text":"1:3"}],"answer":"b","explanation":"The key gives 1:1 for the mortar used to fill the frogs. It is a rule-of-thumb value from estimating practice.","marks":1,"source":{"kind":"past","set":13,"question":42,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q42 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-13-067","src":"PAST-13-067","text":"The suitable contour interval for a map with scale 1:10000 is","options":[{"key":"a","text":"2 m"},{"key":"b","text":"5 m"},{"key":"c","text":"10 m"},{"key":"d","text":"20 m"}],"answer":"a","explanation":"A common rule is contour interval \\(\\approx \\dfrac{25}{\\text{cm per km}}\\). At 1:10,000 (10 cm per km) that gives about 2-2.5 m, so a 2 m interval suits the map.","marks":2,"source":{"kind":"past","set":13,"question":67,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q67 · 2 marks"},"topic":"ACiE0105"},{"id":"PAST-13-068","src":"PAST-13-068","text":"If the intercept on a vertical staff is observed as 0.75 m from a tachometer, the horizontal distance between the tachometer and staff is","options":[{"key":"a","text":"7.5 m"},{"key":"b","text":"25 m"},{"key":"c","text":"50 m"},{"key":"d","text":"75 m"}],"answer":"d","explanation":"With multiplying constant 100 and additive constant 0 (anallactic lens), \\[D = 100 \\times 0.75 = 75\\ \\text{m}\\]","marks":2,"source":{"kind":"past","set":13,"question":68,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q68 · 2 marks"},"topic":"ACiE0105"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-13-001","src":"PAST-13-001","text":"An oedometer is used to measure","options":[{"key":"a","text":"consolidation"},{"key":"b","text":"speed"},{"key":"c","text":"velocity"},{"key":"d","text":"pressure"}],"answer":"a","explanation":"The oedometer (consolidometer) loads a laterally confined soil specimen to measure its consolidation (compressibility and rate of settlement).","marks":1,"source":{"kind":"past","set":13,"question":1,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q1 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-13-019","src":"PAST-13-019","text":"The formula of shear strength of soil is","options":[{"key":"a","text":"S = c + σtanθ"},{"key":"b","text":"S = tanθ × ki"},{"key":"c","text":"C = S + σtanθ"},{"key":"d","text":"S = ctanθ + σ"}],"answer":"a","explanation":"By Mohr-Coulomb, \\[s = c + \\sigma\\tan\\phi\\] where \\(\\phi\\) is the angle of shearing resistance (written \\(\\theta\\) here).","marks":1,"source":{"kind":"past","set":13,"question":19,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q19 · 1 mark"},"topic":"ACiE0203"},{"id":"PAST-13-021","src":"PAST-13-021","text":"A wall is considered smooth by","options":[{"key":"a","text":"Rankine theory"},{"key":"b","text":"Column theory"},{"key":"c","text":"Bligh theory"},{"key":"d","text":"Khosla's theory"}],"answer":"a","explanation":"Rankine's earth-pressure theory assumes a smooth vertical back, so there is no wall friction. Coulomb's theory allows wall friction δ.","marks":1,"source":{"kind":"past","set":13,"question":21,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q21 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-13-028","src":"PAST-13-028","text":"Expulsion of pore water from soil is called","options":[{"key":"a","text":"Consolidation"},{"key":"b","text":"Compaction"},{"key":"c","text":"Pressurization"},{"key":"d","text":"Densification"}],"answer":"a","explanation":"Consolidation is the gradual volume reduction of saturated soil as pore water is squeezed out under sustained load. Compaction expels air.","marks":1,"source":{"kind":"past","set":13,"question":28,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q28 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-13-051","src":"PAST-13-051","text":"Due to long term loading, when all the water comes out of the pores, it is called","options":[{"key":"a","text":"Compaction"},{"key":"b","text":"Consolidation"},{"key":"c","text":"Densification"},{"key":"d","text":"Water expulsion"}],"answer":"b","explanation":"The time-dependent expulsion of pore water under sustained load is consolidation.","marks":1,"source":{"kind":"past","set":13,"question":51,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q51 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-13-052","src":"PAST-13-052","text":"Scour depth and frost depth are parameters that govern the","options":[{"key":"a","text":"depth of foundation"},{"key":"b","text":"type of foundation"},{"key":"c","text":"type of superstructure"},{"key":"d","text":"none of the above"}],"answer":"a","explanation":"Foundations must be taken below the probable scour depth (bridges, river banks) and below the frost-penetration depth. Both therefore set the minimum depth of foundation.","marks":1,"source":{"kind":"past","set":13,"question":52,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q52 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-13-059","src":"PAST-13-059","text":"For a cohesionless soil which is losing soil from its sides, what should be provided?","options":[{"key":"a","text":"Sheet piles"},{"key":"b","text":"Anchor on top"},{"key":"c","text":"Both a and b"},{"key":"d","text":"None of the above"}],"answer":"c","explanation":"The sides of an excavation in loose cohesionless soil are supported by sheet piles, anchored or strutted at the top so that they do not deflect and let soil run in.","marks":1,"source":{"kind":"past","set":13,"question":59,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q59 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-13-079","src":"PAST-13-079","text":"A soil has a porosity of 30%. Its void ratios in the loosest and densest states are 0.92 and 0.35 respectively. What will be its density index?","options":[{"key":"a","text":"0.865"},{"key":"b","text":"0.872"},{"key":"c","text":"0.861"},{"key":"d","text":"0.883"}],"answer":"c","explanation":"The in-situ void ratio is \\[e = \\dfrac{n}{1 - n} = \\dfrac{0.3}{0.7} = 0.429\\] so the density index is \\[\\begin{aligned} I_D &amp;= \\dfrac{e_{max} - e}{e_{max} - e_{min}} \\\\ &amp;= \\dfrac{0.92 - 0.429}{0.92 - 0.35} \\\\ &amp;\\approx 0.861 \\end{aligned}\\] (The paper lists the two void ratios the other way round.)","marks":2,"source":{"kind":"past","set":13,"question":79,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q79 · 2 marks"},"topic":"ACiE0201"},{"id":"PAST-13-080","src":"PAST-13-080","text":"Find the vertical pressure σ<sub>z</sub> at depth 10 m under a uniformly loaded circular area of radius 1000 m with a load intensity of 80 kN/m<sup>2</sup> (k = 1).","options":[{"key":"a","text":"51 kN/m<sup>2</sup>"},{"key":"b","text":"54 kN/m<sup>2</sup>"},{"key":"c","text":"80 kN/m<sup>2</sup>"},{"key":"d","text":"12 kN/m<sup>2</sup>"}],"answer":"c","explanation":"Under the centre of a uniformly loaded circle, \\[\\sigma_z = q\\left[1 - \\left(\\dfrac{1}{1 + r^2}\\right)^{3{/}2}\\right]\\] where \\(r = \\dfrac{R}{z}\\). With \\(r = 100\\) the bracket is practically 1, so \\(\\sigma_z \\approx q = 80\\) kN per m<sup>2</sup>.","marks":2,"source":{"kind":"past","set":13,"question":80,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q80 · 2 marks"},"topic":"ACiE0202"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-13-023","src":"PAST-13-023","text":"The most accurate method to determine average precipitation is","options":[{"key":"a","text":"Isohyetal method"},{"key":"b","text":"Thiessen polygons"},{"key":"c","text":"Grid method"},{"key":"d","text":"Arithmetic average"}],"answer":"a","explanation":"The isohyetal method uses contours of equal rainfall drawn with judgement of the terrain and storm pattern, so it is generally the most accurate.","marks":1,"source":{"kind":"past","set":13,"question":23,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q23 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-13-024","src":"PAST-13-024","text":"Cold frontal precipitation is formed due to","options":[{"key":"a","text":"an advancing cold air mass meeting warmer air; cold fronts move faster than warm fronts"},{"key":"b","text":"a large mass of air being forced to rise across landform barriers, such as high mountain ranges, plateaus and hills"},{"key":"c","text":"heating of the ground surface: the air warms, expands and rises to a great height and is replaced by colder air; as the rising air cools it becomes saturated and condenses, forming clouds and, on further cooling, precipitation"},{"key":"d","text":"all of the above"}],"answer":"a","explanation":"At a cold front, advancing dense cold air wedges under the warm air and lifts it sharply, giving short, intense showers. Options (b) and (c) describe orographic and convective precipitation.","marks":1,"source":{"kind":"past","set":13,"question":24,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q24 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-13-025","src":"PAST-13-025","text":"What property of water makes (a drop of) it spherical?","options":[{"key":"a","text":"Surface tension"},{"key":"b","text":"Viscosity"},{"key":"c","text":"Pressure"},{"key":"d","text":"Cavitation"}],"answer":"a","explanation":"Surface tension pulls a free drop into the shape with the least surface area for its volume, which is a sphere.","marks":1,"source":{"kind":"past","set":13,"question":25,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q25 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-13-039","src":"PAST-13-039","text":"The spherical shape of a raindrop after falling is due to","options":[{"key":"a","text":"Viscosity"},{"key":"b","text":"Surface tension"},{"key":"c","text":"Density"},{"key":"d","text":"Cavitation"}],"answer":"b","explanation":"Surface tension minimises the free surface area of the drop, so small drops take a spherical shape.","marks":1,"source":{"kind":"past","set":13,"question":39,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q39 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-13-062","src":"PAST-13-062","text":"What is the bulk modulus of a body that experienced a change of pressure of 5×10<sup>4</sup> N/m<sup>2</sup> and whose volume goes from 4 cm<sup>3</sup> to 3.9 cm<sup>3</sup>?","options":[{"key":"a","text":"1.25×10<sup>3</sup> N/m<sup>2</sup>"},{"key":"b","text":"2.00×10<sup>6</sup> N/m<sup>2</sup>"},{"key":"c","text":"1.25×10<sup>5</sup> N/m<sup>2</sup>"},{"key":"d","text":"1.25 N/m<sup>2</sup>"}],"answer":"b","explanation":"The bulk modulus is \\[\\begin{aligned} K &amp;= \\dfrac{\\Delta p}{\\Delta V{/}V} = \\dfrac{5 \\times 10^4}{0.1{/}4} \\\\ &amp;= 2 \\times 10^6\\ \\text{N/m}^2 \\end{aligned}\\] The paper prints option (b) as \\(2.00 \\times 10^5\\), but the key's own working gives \\(2 \\times 10^6\\), so the value is corrected here.","marks":2,"source":{"kind":"past","set":13,"question":62,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q62 · 2 marks"},"topic":"ACiE0301"},{"id":"PAST-13-065","src":"PAST-13-065","text":"A hydraulic press has a ram of 30 cm diameter and a plunger of 2 cm diameter. It is used for lifting a weight of 35 kN. Find the force required at the plunger.","options":[{"key":"a","text":"233.3 N"},{"key":"b","text":"311.1 N"},{"key":"c","text":"466.6 N"},{"key":"d","text":"155.5 N"}],"answer":"d","explanation":"By Pascal's law \\(\\dfrac{F}{a} = \\dfrac{W}{A}\\), so \\[\\begin{aligned} F &amp;= 35{,}000 \\times \\left(\\dfrac{2}{30}\\right)^2 \\\\ &amp;\\approx 155.5\\ \\text{N} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":13,"question":65,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q65 · 2 marks"},"topic":"ACiE0302"},{"id":"PAST-13-066","src":"PAST-13-066","text":"The pressure at a point in a fluid is 4.9 N/cm<sup>2</sup>. Find the height when the fluid under consideration is oil of specific gravity 0.85.","options":[{"key":"a","text":"5.83 m"},{"key":"b","text":"11.66 m"},{"key":"c","text":"17.49 m"},{"key":"d","text":"8.74 m"}],"answer":"a","explanation":"The pressure head is \\[\\begin{aligned} h &amp;= \\dfrac{p}{\\rho g} = \\dfrac{49{,}000}{850 \\times 9.81} \\\\ &amp;\\approx 5.9\\ \\text{m} \\end{aligned}\\] closest to option (a), 5.83 m.","marks":2,"source":{"kind":"past","set":13,"question":66,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q66 · 2 marks"},"topic":"ACiE0302"},{"id":"PAST-13-078","src":"PAST-13-078","text":"The weight of a person on Earth is 100 N. What will the weight be if the man is on a planet having acceleration due to gravity 1/6th of Earth's?","options":[{"key":"a","text":"10.66 N"},{"key":"b","text":"16.67 N"},{"key":"c","text":"166.7 N"},{"key":"d","text":"67.76 N"}],"answer":"b","explanation":"Mass is unchanged and weight is \\(mg\\), so the weight becomes \\[\\dfrac{100}{6} \\approx 16.67\\ \\text{N}\\]","marks":2,"source":{"kind":"past","set":13,"question":78,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q78 · 2 marks"},"topic":"ACiE0302"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-13-012","src":"PAST-13-012","text":"The formula of the flexure equation is","options":[{"key":"a","text":"M/I = σ/y"},{"key":"b","text":"M/k = /y"},{"key":"c","text":"M/I = σ/2y"},{"key":"d","text":"All of the above"}],"answer":"a","explanation":"The bending equation is \\[\\dfrac{M}{I} = \\dfrac{\\sigma}{y} = \\dfrac{E}{R}\\]","marks":1,"source":{"kind":"past","set":13,"question":12,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q12 · 1 mark"},"topic":"ACiE0403"},{"id":"PAST-13-020","src":"PAST-13-020","text":"When a train moves on a simply supported beam, the BM is maximum","options":[{"key":"a","text":"at end"},{"key":"b","text":"at centre"},{"key":"c","text":"at support"},{"key":"d","text":"zero BM"}],"answer":"b","explanation":"The absolute maximum BM under a moving train occurs near midspan: under the wheel load closest to the resultant, placed so the centre of span bisects the distance between them. Moment at the supports is zero.","marks":1,"source":{"kind":"past","set":13,"question":20,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q20 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-13-041","src":"PAST-13-041","text":"For a simply supported beam, if the bending moment is constant, what will be the shear force?","options":[{"key":"a","text":"Zero"},{"key":"b","text":"Constant"},{"key":"c","text":"Uniformly varying"},{"key":"d","text":"None of the above"}],"answer":"a","explanation":"Since \\(S = \\dfrac{dM}{dx}\\), a constant moment means zero shear throughout (pure bending).","marks":1,"source":{"kind":"past","set":13,"question":41,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q41 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-13-050","src":"PAST-13-050","text":"If m1 and m2 are the members of two individual simple trusses of a compound truss, the compound truss will be rigid and determinate if","options":[{"key":"a","text":"m = m1 + m2"},{"key":"b","text":"m = m1 + m2 + 1"},{"key":"c","text":"m = m1 + m2 + 3"},{"key":"d","text":"none of the above"}],"answer":"c","explanation":"Two rigid simple trusses joined by three non-concurrent, non-parallel bars form a rigid determinate compound truss, so \\[m = m_1 + m_2 + 3\\]","marks":1,"source":{"kind":"past","set":13,"question":50,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q50 · 1 mark"},"topic":"ACiE0405"},{"id":"PAST-13-064","src":"PAST-13-064","text":"A load of 20 kN acts on a simply supported beam, making an angle of 30 degree to the horizontal. The cross-section area of the beam is 1000 mm<sup>2</sup>. Find the axial force.","options":[{"key":"a","text":"17.32 kN"},{"key":"b","text":"10 kN"},{"key":"c","text":"20 kN"},{"key":"d","text":"34.64 kN"}],"answer":"a","explanation":"The component along the (horizontal) beam axis is 20 cos30° = 17.32 kN. The transverse component 20 sin30° = 10 kN causes bending.","marks":2,"source":{"kind":"past","set":13,"question":64,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q64 · 2 marks"},"topic":"ACiE0401"},{"id":"PAST-13-073","src":"PAST-13-073","text":"The bending moment at 2 m from the left support of a simply supported beam of length 8 m, with 1 kN/m load acting over the entire span, is","options":[{"key":"a","text":"4.5 kNm"},{"key":"b","text":"6 kNm"},{"key":"c","text":"8 kNm"},{"key":"d","text":"16 kNm"}],"answer":"b","explanation":"The reaction is \\(R = 4\\) kN, so \\[\\begin{aligned} M(2) &amp;= 4 \\times 2 - \\dfrac{1 \\times 2^2}{2} \\\\ &amp;= 8 - 2 = 6 \\end{aligned}\\] kNm.","marks":2,"source":{"kind":"past","set":13,"question":73,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q73 · 2 marks"},"topic":"ACiE0401"},{"id":"PAST-13-077","src":"PAST-13-077","text":"A three-hinged parabolic arch is subjected to a load w at L/4 distance from the left support. The rise of the crown is 4 m, the span is 20 m and w is 80 kN. The horizontal support reaction at the left support is","options":[{"key":"a","text":"20 kN"},{"key":"b","text":"40 kN"},{"key":"c","text":"50 kN"},{"key":"d","text":"60 kN"}],"answer":"c","explanation":"The right support reaction is \\[V_B = \\dfrac{80 \\times 5}{20} = 20\\ \\text{kN}\\] Taking moments about the crown hinge for the unloaded right half, \\[H \\times 4 = 20 \\times 10\\] so \\(H = 50\\) kN.","marks":2,"source":{"kind":"past","set":13,"question":77,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q77 · 2 marks"},"topic":"ACiE0405"}]},{"name":"Design of Structures","questions":[{"id":"PAST-13-014","src":"PAST-13-014","text":"Which water is used in cement concrete?","options":[{"key":"a","text":"Potable water"},{"key":"b","text":"Acidic water"},{"key":"c","text":"Impure water"},{"key":"d","text":"Water from sewer can also be used if drinking water is not available easily"}],"answer":"a","explanation":"IS 456: water fit for drinking is generally satisfactory for mixing and curing concrete. Acidic, impure or sewage water harms setting, strength and durability.","marks":1,"source":{"kind":"past","set":13,"question":14,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q14 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-13-015","src":"PAST-13-015","text":"Find the maximum anchorage length for D = 20 mm (hooked bar).","options":[{"key":"a","text":"220 mm"},{"key":"b","text":"320 mm"},{"key":"c","text":"420 mm"},{"key":"d","text":"520 mm"}],"answer":"b","explanation":"A standard U (\\(180^\\circ\\)) hook is worth \\(16\\phi\\) of anchorage: \\[16 \\times 20 = 320\\ \\text{mm}\\]","marks":1,"source":{"kind":"past","set":13,"question":15,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q15 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-13-032","src":"PAST-13-032","text":"The tensile strength of concrete is about","options":[{"key":"a","text":"10% of compressive strength"},{"key":"b","text":"20% of compressive strength"},{"key":"c","text":"15% of compressive strength"},{"key":"d","text":"25% of compressive strength"}],"answer":"a","explanation":"The direct tensile strength of concrete is only about 8–12% (roughly one-tenth) of its compressive strength, which is why steel is used to take tension.","marks":1,"source":{"kind":"past","set":13,"question":32,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q32 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-13-033","src":"PAST-13-033","text":"The tensile strength of reinforcement in RCC is reduced by","options":[{"key":"a","text":"15%, as FOS for limit state method for steel is 1.15 and design strength is σ/1.15"},{"key":"b","text":"25%, as FOS for limit state method for steel is 1.15 and design strength is σ/1.15"},{"key":"c","text":"35%, as FOS for limit state method for steel is 1.15 and design strength is σ/1.15"},{"key":"d","text":"15%, as FOS for limit state method for steel is 1.15 and design strength is σ/2.25"}],"answer":"a","explanation":"In limit state design the steel strength is divided by \\(\\gamma_m = 1.15\\), giving \\[\\dfrac{f_y}{1.15} = 0.87f_y\\] a reduction of about 13-15%.","marks":1,"source":{"kind":"past","set":13,"question":33,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q33 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-13-046","src":"PAST-13-046","text":"Which is not considered as dead load?","options":[{"key":"a","text":"Floor of class room"},{"key":"b","text":"Students"},{"key":"c","text":"Columns"},{"key":"d","text":"Wall"}],"answer":"b","explanation":"Floors, columns and walls are permanent self-weights (dead load). Students (occupants) are imposed or live load.","marks":1,"source":{"kind":"past","set":13,"question":46,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q46 · 1 mark"},"topic":"ACiE0501"},{"id":"PAST-13-047","src":"PAST-13-047","text":"The slump test is a measure of","options":[{"key":"a","text":"Tensile strength of concrete"},{"key":"b","text":"Strength of concrete"},{"key":"c","text":"Consistency"},{"key":"d","text":"Roughness"}],"answer":"c","explanation":"The slump test measures the consistency (workability) of fresh concrete.","marks":1,"source":{"kind":"past","set":13,"question":47,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q47 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-13-076","src":"PAST-13-076","text":"A reinforced concrete beam having a width of 250 mm and an effective depth of 400 mm is reinforced with Fe415 steel. As per the provisions of IS 456:2000, the minimum amount of tensile reinforcement is","options":[{"key":"a","text":"180 mm<sup>2</sup>"},{"key":"b","text":"205 mm<sup>2</sup>"},{"key":"c","text":"210 mm<sup>2</sup>"},{"key":"d","text":"250 mm<sup>2</sup>"}],"answer":"b","explanation":"The minimum tensile reinforcement is \\[\\begin{aligned} A_{s,min} &amp;= \\dfrac{0.85bd}{f_y} \\\\ &amp;= \\dfrac{0.85 \\times 250 \\times 400}{415} \\\\ &amp;\\approx 205\\ \\text{mm}^2 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":13,"question":76,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q76 · 2 marks"},"topic":"ACiE0503"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-13-004","src":"PAST-13-004","text":"Why is the E. coli test performed?","options":[{"key":"a","text":"To confirm the water has been contaminated by faeces"},{"key":"b","text":"To detect the turbidity"},{"key":"c","text":"To confirm the presence of bad odour"},{"key":"d","text":"To confirm the presence of coloured bacteria"}],"answer":"a","explanation":"E. coli lives in the intestines of warm-blooded animals, so its presence shows faecal contamination and possible pathogens.","marks":1,"source":{"kind":"past","set":13,"question":4,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q4 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-13-005","src":"PAST-13-005","text":"The COD/BOD of country sewage in general is","options":[{"key":"a","text":"Greater than 1"},{"key":"b","text":"Less than 1"},{"key":"c","text":"Equal to −1"},{"key":"d","text":"All of the above"}],"answer":"a","explanation":"COD oxidises both biodegradable and non-biodegradable matter, so COD always exceeds BOD and the ratio is greater than 1 (about 1.25–2.5 for domestic sewage).","marks":1,"source":{"kind":"past","set":13,"question":5,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q5 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-13-011","src":"PAST-13-011","text":"NDRRMA falls under which ministry?","options":[{"key":"a","text":"Ministry of Home Affairs (MOHA)"},{"key":"b","text":"Ministry of Physical Infrastructure"},{"key":"c","text":"Ministry of Energy"},{"key":"d","text":"Prime Minister's Office"}],"answer":"a","explanation":"The National Disaster Risk Reduction and Management Authority works under the Ministry of Home Affairs.","marks":1,"source":{"kind":"past","set":13,"question":11,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q11 · 1 mark"},"topic":"ACiE0606"},{"id":"PAST-13-022","src":"PAST-13-022","text":"The rough joint used to join concrete pipes is","options":[{"key":"a","text":"spigot joint"},{"key":"b","text":"bandage joint"},{"key":"c","text":"rough joint"},{"key":"d","text":"none"}],"answer":"b","explanation":"The key identifies the bandage joint, a band of cement mortar and cloth wrapped round butting concrete pipe ends. It is a simple, rough joint suitable only for non-pressure lines.","marks":1,"source":{"kind":"past","set":13,"question":22,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q22 · 1 mark"},"topic":"ACiE0604"},{"id":"PAST-13-031","src":"PAST-13-031","text":"Which of the following is not affected by chlorination?","options":[{"key":"a","text":"Dissolved oxygen (DO)"},{"key":"b","text":"Dissolved CO<sub>2</sub>"},{"key":"c","text":"Dissolved bacteria"},{"key":"d","text":"Initial oxygen demand"}],"answer":"a","explanation":"Chlorine kills bacteria and satisfies the demand exerted by oxidisable substances, but it does not change the dissolved oxygen content.","marks":1,"source":{"kind":"past","set":13,"question":31,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q31 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-13-036","src":"PAST-13-036","text":"Which bacteria can function with and without oxygen?","options":[{"key":"a","text":"Facultative bacteria"},{"key":"b","text":"Mesophilic bacteria"},{"key":"c","text":"Thermophilic bacteria"},{"key":"d","text":"All of the above"}],"answer":"a","explanation":"Facultative bacteria use free oxygen when it is available and switch to anaerobic metabolism when it is not. Mesophilic and thermophilic refer to temperature ranges.","marks":1,"source":{"kind":"past","set":13,"question":36,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q36 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-13-053","src":"PAST-13-053","text":"Which of the following is NOT included during scoping of EIA?","options":[{"key":"a","text":"Conducting impact assessment and contingency planning"},{"key":"b","text":"Setting criteria for the project"},{"key":"c","text":"Raising fund"},{"key":"d","text":"All of the above"}],"answer":"a","explanation":"Scoping decides which issues, alternatives and boundaries the EIA will study and prepares its ToR. Assessing the impacts and planning mitigation come later, in the EIA study itself.","marks":1,"source":{"kind":"past","set":13,"question":53,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q53 · 1 mark"},"topic":"ACiE0606"},{"id":"PAST-13-057","src":"PAST-13-057","text":"Chlorination of water does not decrease","options":[{"key":"a","text":"organic matter"},{"key":"b","text":"iron"},{"key":"c","text":"dissolved oxygen"},{"key":"d","text":"all of the above"}],"answer":"c","explanation":"Chlorine oxidises organic matter and iron (they form part of the chlorine demand) but does not remove dissolved oxygen.","marks":1,"source":{"kind":"past","set":13,"question":57,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q57 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-13-058","src":"PAST-13-058","text":"A sanitary sewer is expected to run","options":[{"key":"a","text":"full"},{"key":"b","text":"90% full"},{"key":"c","text":"two third full"},{"key":"d","text":"half full"}],"answer":"c","explanation":"Sanitary sewers are designed to run partly full, about two-thirds to three-quarters of the depth at peak flow. The free space allows for ventilation and flow fluctuations.","marks":1,"source":{"kind":"past","set":13,"question":58,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q58 · 1 mark"},"topic":"ACiE0604"},{"id":"PAST-13-070","src":"PAST-13-070","text":"If the five day BOD is 276 mg/l and the ultimate BOD is 380 mg/l, at what rate is the waste oxidized?","options":[{"key":"a","text":"0.1125/day"},{"key":"b","text":"0.1125/hour"},{"key":"c","text":"0.2215/day"},{"key":"d","text":"0.213/day"}],"answer":"a","explanation":"From \\[\\text{BOD}_5 = L_0(1 - 10^{-5k})\\] we get \\[10^{-5k} = 1 - \\dfrac{276}{380} = 0.274\\] so \\(k = 0.1125\\) per day (base 10).","marks":2,"source":{"kind":"past","set":13,"question":70,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q70 · 2 marks"},"topic":"ACiE0605"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-13-008","src":"PAST-13-008","text":"When is duty maximum?","options":[{"key":"a","text":"Highest in the field and lowest at the head of the main canal"},{"key":"b","text":"Highest in the field and lowest at the head of the main capital"},{"key":"c","text":"Lowest in the field and highest at the head of the main canal"},{"key":"d","text":"Both a and c"}],"answer":"a","explanation":"Duty is area irrigated per cumec. At the canal head the same water must also cover all the conveyance losses, so duty is lowest there and highest at the field.","marks":1,"source":{"kind":"past","set":13,"question":8,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q8 · 1 mark"},"topic":"ACiE0701"},{"id":"PAST-13-038","src":"PAST-13-038","text":"The (Lacey) scour depth can be calculated using the formula","options":[{"key":"a","text":"R = 1.35(q<sup>2</sup>/f)<sup>1/3</sup>"},{"key":"b","text":"R = 1.35(q<sup>2</sup>/f)<sup>2/3</sup>"},{"key":"c","text":"R = 1.35(q<sup>2</sup>/f)<sup>5/3</sup>"},{"key":"d","text":"All of the above"}],"answer":"a","explanation":"Lacey's normal scour depth for a known discharge intensity \\(q\\) is \\[R = 1.35\\left(\\dfrac{q^2}{f}\\right)^{1{/}3}\\] where \\(f\\) is the silt factor.","marks":1,"source":{"kind":"past","set":13,"question":38,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q38 · 1 mark"},"topic":"ACiE0704"},{"id":"PAST-13-045","src":"PAST-13-045","text":"Which of the following structures is constructed to separate the under sluice from the main weir?","options":[{"key":"a","text":"Marginal bund"},{"key":"b","text":"Divide wall"},{"key":"c","text":"Head regulator"},{"key":"d","text":"Cross regulator"}],"answer":"b","explanation":"A divide wall at right angles to the weir separates the undersluice bays from the main weir and forms a still pocket in front of the head regulator.","marks":1,"source":{"kind":"past","set":13,"question":45,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q45 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-13-048","src":"PAST-13-048","text":"Under sluices are provided at","options":[{"key":"a","text":"the same height as the river bed level"},{"key":"b","text":"below river bed level"},{"key":"c","text":"a height more than that of the cross regulator"},{"key":"d","text":"none of the above"}],"answer":"a","explanation":"Undersluices have their crest at a low level, about the deep river bed, below the main weir crest. This lets them scour silt from in front of the canal head and keep the deep channel there.","marks":1,"source":{"kind":"past","set":13,"question":48,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q48 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-13-049","src":"PAST-13-049","text":"A cross regulator is provided on the main canal downstream of the off-take canal","options":[{"key":"a","text":"to regulate water supply in the off-take canal"},{"key":"b","text":"to increase the water head upstream when the main canal is running with low supplies"},{"key":"c","text":"to overflow excessive flow of water"},{"key":"d","text":"none of the above"}],"answer":"b","explanation":"By heading up the water in the parent canal, the cross regulator lets the off-taking channel draw its full supply even when the main canal runs low.","marks":1,"source":{"kind":"past","set":13,"question":49,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q49 · 1 mark"},"topic":"ACiE0705"},{"id":"PAST-13-056","src":"PAST-13-056","text":"Guide banks are provided in a river to","options":[{"key":"a","text":"increase the depth of flow"},{"key":"b","text":"decrease the velocity of flow"},{"key":"c","text":"canalize the flow"},{"key":"d","text":"reduce the flood peak"}],"answer":"c","explanation":"Guide banks confine and guide (canalise) the river smoothly through the bridge or barrage waterway and prevent it from outflanking the structure.","marks":1,"source":{"kind":"past","set":13,"question":56,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q56 · 1 mark"},"topic":"ACiE0704"},{"id":"PAST-13-061","src":"PAST-13-061","text":"An irrigation canal is to be designed to deliver 6.25 cumecs to meet the peak Rabi demand of a total of 5100 hectares of cropped area. The estimated canal losses are 25% of the head discharge. The duty on capacity of this small canal will be","options":[{"key":"a","text":"512 ha/cumecs"},{"key":"b","text":"612 ha/cumecs"},{"key":"c","text":"712 ha/cumecs"},{"key":"d","text":"653 ha/cumecs"}],"answer":"b","explanation":"The head discharge is \\(\\dfrac{6.25}{0.75} = 8.33\\) cumecs, so the duty on capacity is \\[\\dfrac{5100}{8.33} \\approx 612\\] hectares per cumec.","marks":2,"source":{"kind":"past","set":13,"question":61,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q61 · 2 marks"},"topic":"ACiE0702"},{"id":"PAST-13-063","src":"PAST-13-063","text":"According to Lacey's regime theory, what will be the regime scour depth for a channel in soil having a silt factor of unity and carrying a discharge of 96 m<sup>3</sup>/s, if the base width of the channel is 12 m?","options":[{"key":"a","text":"2.7 m"},{"key":"b","text":"10.8 m"},{"key":"c","text":"8.0 m"},{"key":"d","text":"5.4 m"}],"answer":"d","explanation":"The discharge intensity is \\(q = \\dfrac{96}{12} = 8\\) m<sup>3</sup> per s per m, so \\[\\begin{aligned} R &amp;= 1.35\\left(\\dfrac{q^2}{f}\\right)^{1{/}3} \\\\ &amp;= 1.35 \\times 64^{1{/}3} \\\\ &amp;= 1.35 \\times 4 = 5.4\\ \\text{m} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":13,"question":63,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q63 · 2 marks"},"topic":"ACiE0704"},{"id":"PAST-13-071","src":"PAST-13-071","text":"Lacey's silt factor for medium silt whose average grain size is 0.25 mm is likely to be","options":[{"key":"a","text":"0.66"},{"key":"b","text":"0.77"},{"key":"c","text":"0.88"},{"key":"d","text":"0.99"}],"answer":"c","explanation":"Lacey's silt factor is \\[\\begin{aligned} f &amp;= 1.76\\sqrt{d} = 1.76\\sqrt{0.25} \\\\ &amp;= 0.88 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":13,"question":71,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q71 · 2 marks"},"topic":"ACiE0702"}]},{"name":"Hydropower","questions":[{"id":"PAST-13-002","src":"PAST-13-002","text":"The fore poling method is generally adopted for tunnelling","options":[{"key":"a","text":"in soft ground"},{"key":"b","text":"in hard ground"},{"key":"c","text":"in rock"},{"key":"d","text":"in firm ground"}],"answer":"a","explanation":"Forepoling drives poles or boards ahead of the face to support loose, soft or running ground as excavation advances. Rock tunnels use drilling and blasting.","marks":1,"source":{"kind":"past","set":13,"question":2,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q2 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-13-003","src":"PAST-13-003","text":"The procedure of removal of rock protrusions by hammering immediately after the blasting is","options":[{"key":"a","text":"Blasting"},{"key":"b","text":"Mucking"},{"key":"c","text":"Hardening"},{"key":"d","text":"Tempering"}],"answer":"b","explanation":"The operation is strictly called scaling. Of the given options, the key takes mucking, the clearing of broken rock after a blast.","marks":1,"source":{"kind":"past","set":13,"question":3,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q3 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-13-016","src":"PAST-13-016","text":"The following operations are required for tunnelling in rocky terrain: 1. Removing the foul gases, 2. Marking the tunnel profile, 3. Setting up and drilling, 4. Checking misfire, 5. Mucking. The correct sequence is","options":[{"key":"a","text":"1, 2, 3, 4, 5"},{"key":"b","text":"2, 3, 5, 4, 1"},{"key":"c","text":"4, 2, 1, 3, 5"},{"key":"d","text":"2, 3, 1, 4, 5"}],"answer":"d","explanation":"The profile is marked, drill holes are set up and drilled, and the charges are blasted. The fumes are then removed by ventilation, the face is checked for misfires, and only then is the muck cleared. (The paper's option (d) is cut off after '4,'.)","marks":1,"source":{"kind":"past","set":13,"question":16,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q16 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-13-018","src":"PAST-13-018","text":"Pick up the correct statement from the following during tunnel excavation.","options":[{"key":"a","text":"Oxygen should not be less than 19.5%"},{"key":"b","text":"Carbon dioxide should not be more than 0.5%"},{"key":"c","text":"Hydrogen sulphide should not be more than 0.001%"},{"key":"d","text":"All of the above"}],"answer":"d","explanation":"All three are the standard air-quality limits for tunnel work: O<sub>2</sub> at least 19.5%, CO<sub>2</sub> at most 0.5% and H<sub>2</sub>S at most 0.001% (10 ppm).","marks":1,"source":{"kind":"past","set":13,"question":18,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q18 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-13-054","src":"PAST-13-054","text":"Which statement is not true about a hydroelectric plant?","options":[{"key":"a","text":"It has high cost and takes a lot of time in construction"},{"key":"b","text":"It is more environmentally friendly compared to others"},{"key":"c","text":"It becomes less effective with time"},{"key":"d","text":"All of the above"}],"answer":"c","explanation":"Hydro plants do have high first costs and long construction periods, and they are cleaner than thermal plants. They are long-lived (50+ years) and keep their efficiency with routine maintenance, so (c) is the untrue statement. The source key gives (d) while its note calls every statement true.","marks":1,"source":{"kind":"past","set":13,"question":54,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q54 · 1 mark"},"topic":"ACiE0801"},{"id":"PAST-13-060","src":"PAST-13-060","text":"The base width of a solid gravity dam is 35 m and the specific gravity of the dam material is 2.45. What is the approximate allowable height of the dam having an elementary profile, without considering the uplift?","options":[{"key":"a","text":"54.8 m"},{"key":"b","text":"55.5 m"},{"key":"c","text":"59 m"},{"key":"d","text":"25.8 m"}],"answer":"a","explanation":"For no tension with no uplift, \\(B = \\dfrac{H}{\\sqrt{S_c}}\\), so \\[\\begin{aligned} H &amp;= B\\sqrt{S_c} = 35 \\times \\sqrt{2.45} \\\\ &amp;\\approx 54.8\\ \\text{m} \\end{aligned}\\]","marks":1,"source":{"kind":"past","set":13,"question":60,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q60 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-13-072","src":"PAST-13-072","text":"A canal drop is 6 metres and the discharge available through the turbine is 50 cumec. Find the electrical energy available.","options":[{"key":"a","text":"2352 kW"},{"key":"b","text":"2352 MW"},{"key":"c","text":"235.2 kW"},{"key":"d","text":"2.352 kW"}],"answer":"a","explanation":"The water power is \\[9.81 \\times 50 \\times 6 \\approx 2943\\ \\text{kW}\\] At an overall efficiency of about 80% the electrical output is about 2352 kW.","marks":2,"source":{"kind":"past","set":13,"question":72,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q72 · 2 marks"},"topic":"ACiE0802"}]},{"name":"Transportation","questions":[{"id":"PAST-13-026","src":"PAST-13-026","text":"In which type of parking can the maximum number of vehicles be parked?","options":[{"key":"a","text":"Perpendicular or 90 degree parking"},{"key":"b","text":"Parallel parking"},{"key":"c","text":"45 degree parking"},{"key":"d","text":"75 degree parking"}],"answer":"a","explanation":"For a given kerb length, 90° (perpendicular) parking accommodates the most cars, although manoeuvring is hardest. Parallel parking accommodates the fewest.","marks":1,"source":{"kind":"past","set":13,"question":26,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q26 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-13-029","src":"PAST-13-029","text":"Bitumen is extracted from","options":[{"key":"a","text":"Petroleum products"},{"key":"b","text":"Crop products"},{"key":"c","text":"Acidic products"},{"key":"d","text":"Indovengaris products"}],"answer":"a","explanation":"Paving bitumen is the heavy residue left after fractional distillation of crude petroleum.","marks":1,"source":{"kind":"past","set":13,"question":29,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q29 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-13-034","src":"PAST-13-034","text":"The bitumen extraction test is done at","options":[{"key":"a","text":"3600 rpm at 110 degree Celsius"},{"key":"b","text":"2600 rpm at 110 degree Celsius"},{"key":"c","text":"3600 rpm at 300 degree Celsius"},{"key":"d","text":"1600 rpm at 110 degree Celsius"}],"answer":"a","explanation":"In the centrifuge extraction test the mix is washed with solvent and spun at up to 3600 rpm. The recovered aggregate is dried at about 110°C to find the binder content.","marks":1,"source":{"kind":"past","set":13,"question":34,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q34 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-13-040","src":"PAST-13-040","text":"The minimum width of a single lane road in the Nepal standard is","options":[{"key":"a","text":"2.75 m"},{"key":"b","text":"3.75 m"},{"key":"c","text":"3.5 m"},{"key":"d","text":"5 m"}],"answer":"b","explanation":"The Nepal Road Standard takes a single-lane carriageway width of 3.75 m (3.5 m per lane on multi-lane roads).","marks":1,"source":{"kind":"past","set":13,"question":40,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q40 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-13-043","src":"PAST-13-043","text":"The extra width added to a road (on curves) is","options":[{"key":"a","text":"mechanical + psychological"},{"key":"b","text":"mechanical + psychological shoulder"},{"key":"c","text":"mechanical + psychological + eye sight"},{"key":"d","text":"none of the above"}],"answer":"a","explanation":"Extra widening is mechanical widening (off-tracking) plus psychological widening: \\[W_e = \\dfrac{nl^2}{2R} + \\dfrac{V}{9.5\\sqrt{R}}\\]","marks":1,"source":{"kind":"past","set":13,"question":43,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q43 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-13-055","src":"PAST-13-055","text":"The highway with the highest mobility but least accessibility is","options":[{"key":"a","text":"National highway"},{"key":"b","text":"State highway, major"},{"key":"c","text":"District road"},{"key":"d","text":"Village road"}],"answer":"a","explanation":"Mobility and access trade off. National highways (arterials) carry fast through-traffic with controlled access, while local roads give the most access but the least mobility.","marks":1,"source":{"kind":"past","set":13,"question":55,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q55 · 1 mark"},"topic":"ACiE0901"},{"id":"PAST-13-074","src":"PAST-13-074","text":"The degree of curve is the central angle subtended by an arc of length","options":[{"key":"a","text":"20 m"},{"key":"b","text":"25 m"},{"key":"c","text":"30 m"},{"key":"d","text":"35 m"}],"answer":"c","explanation":"In metric highway practice, the degree of curve is the central angle subtended by a 30 m arc, so \\[R = \\dfrac{1718.9}{D}\\] Some texts use a 20 m chord.","marks":2,"source":{"kind":"past","set":13,"question":74,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q74 · 2 marks"},"topic":"ACiE0902"},{"id":"PAST-13-075","src":"PAST-13-075","text":"If the radius of a horizontal curve is 120 m, then calculate the safe allowable speed.","options":[{"key":"a","text":"50 kmph"},{"key":"b","text":"60 kmph"},{"key":"c","text":"70 kmph"},{"key":"d","text":"80 kmph"}],"answer":"b","explanation":"With \\(e = 0.07\\) and \\(f = 0.15\\), \\[\\begin{aligned} v &amp;= \\sqrt{127R(e + f)} \\\\ &amp;= \\sqrt{127 \\times 120 \\times 0.22} \\\\ &amp;\\approx 58\\ \\text{km/h} \\end{aligned}\\] i.e. about 60 km per h.","marks":2,"source":{"kind":"past","set":13,"question":75,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q75 · 2 marks"},"topic":"ACiE0902"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-13-007","src":"PAST-13-007","text":"The formula of SPI is","options":[{"key":"a","text":"BCWP/BCWS, i.e. earned value/planned value"},{"key":"b","text":"ACWP/BCWS, i.e. earned value/planned value"},{"key":"c","text":"BCWP/ACWS, i.e. earned value/planned value"},{"key":"d","text":"None of the above"}],"answer":"a","explanation":"The schedule performance index is \\[\\text{SPI} = \\dfrac{\\text{EV}}{\\text{PV}} = \\dfrac{\\text{BCWP}}{\\text{BCWS}}\\] \\(\\text{SPI} \\lt 1\\) means behind schedule. \\(\\text{CPI} = \\dfrac{\\text{BCWP}}{\\text{ACWP}}\\) measures cost performance.","marks":1,"source":{"kind":"past","set":13,"question":7,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q7 · 1 mark"},"topic":"AALL1004"},{"id":"PAST-13-010","src":"PAST-13-010","text":"Which angle can we not draw using a set square?","options":[{"key":"a","text":"20 degree"},{"key":"b","text":"15 degree"},{"key":"c","text":"30 degree"},{"key":"d","text":"60 degree"}],"answer":"a","explanation":"The 45° and 30°–60° set squares, alone or combined, give multiples of 15° (15°, 30°, 45°, 60°, 75°, 90°…). 20° cannot be drawn with them.","marks":1,"source":{"kind":"past","set":13,"question":10,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q10 · 1 mark"},"topic":"AALL1001"},{"id":"PAST-13-013","src":"PAST-13-013","text":"Which province of Nepal has the most engineering colleges recognized by NEC?","options":[{"key":"a","text":"Bagmati"},{"key":"b","text":"Lumbini"},{"key":"c","text":"Koshi"},{"key":"d","text":"Sudur Paschim"}],"answer":"a","explanation":"Most NEC-recognised engineering colleges are in Bagmati Province, largely in the Kathmandu valley.","marks":1,"source":{"kind":"past","set":13,"question":13,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q13 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-13-017","src":"PAST-13-017","text":"The formula for effective interest rate is","options":[{"key":"a","text":"r = (1+i/n)<sup>n</sup> − 1"},{"key":"b","text":"r = (1+i/n)<sup>n</sup> − 2"},{"key":"c","text":"r = (1+1/n)<sup>i</sup> − 1"},{"key":"d","text":"r = (2+i/n)<sup>n</sup> − 1"}],"answer":"a","explanation":"For a nominal rate \\(i\\) compounded \\(n\\) times a year, the effective annual rate is \\[r = \\left(1 + \\dfrac{i}{n}\\right)^n - 1\\]","marks":1,"source":{"kind":"past","set":13,"question":17,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q17 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-13-027","src":"PAST-13-027","text":"Finding the future sum of a present investment is called","options":[{"key":"a","text":"Compounding"},{"key":"b","text":"Discounting"},{"key":"c","text":"Dividing"},{"key":"d","text":"Adding money"}],"answer":"a","explanation":"Compounding moves a present amount forward in time: \\[F = P(1 + i)^n\\] Discounting brings future amounts back to present value.","marks":1,"source":{"kind":"past","set":13,"question":27,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q27 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-13-044","src":"PAST-13-044","text":"Which should be considered while selecting a consultancy?","options":[{"key":"a","text":"Quality"},{"key":"b","text":"Quality and cost"},{"key":"c","text":"Cost"},{"key":"d","text":"All of the above"}],"answer":"b","explanation":"Consultants are normally chosen by quality- and cost-based selection (QCBS), which weighs technical quality together with the financial proposal.","marks":1,"source":{"kind":"past","set":13,"question":44,"marks":1,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q44 · 1 mark"},"topic":"AALL1004"},{"id":"PAST-13-069","src":"PAST-13-069","text":"Activities P, Q and R instantly follow activity M, and their current starting times are 12, 19 and 10. So, what is the latest finishing time for activity M?","options":[{"key":"a","text":"11"},{"key":"b","text":"10"},{"key":"c","text":"18"},{"key":"d","text":"Cannot be determined"}],"answer":"b","explanation":"M must finish before the earliest of its successors starts, so its latest finish is \\[\\min(12, 19, 10) = 10\\]","marks":2,"source":{"kind":"past","set":13,"question":69,"marks":2,"date":"2080 Chaitra 1","shift":"3rd shift","reference":"Past Paper Set 13, Q69 · 2 marks"},"topic":"AALL1003"}]}]};
